import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"What is hetzner-dns-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1786889090000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-hetzner-dns-mcp" tabindex="-1">What is hetzner-dns-mcp? <a class="header-anchor" href="#what-is-hetzner-dns-mcp" aria-label="Permalink to “What is hetzner-dns-mcp?”">​</a></h1><p>hetzner-dns-mcp is a <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> server that puts the DNS half of the <a href="https://docs.hetzner.cloud/reference/cloud#zones" target="_blank" rel="noreferrer">Hetzner Cloud API</a> in reach of an MCP client. It speaks JSON-RPC over stdio, exposes 22 tools, and holds no state beyond the confirmation tokens it hands out.</p><p>With it connected, an assistant can answer &quot;which zones do I have and when were they last changed?&quot;, &quot;what does <code>www.example.com</code> resolve to?&quot;, or &quot;add the verification TXT record this provider is asking for&quot; — and can carry out the change, once you have confirmed it.</p><div class="warning custom-block"><p class="custom-block-title">The API this talks to</p><p>This server targets the DNS endpoints of the <strong>Hetzner Cloud API</strong> (<code>api.hetzner.cloud</code>). The old DNS Console API (<code>dns.hetzner.com</code>) was shut down in May 2026, and tokens created there do not work here. If calls come back 401 with a token you are sure is valid, that is almost always the reason — see the <a href="/guide/faq">FAQ</a>.</p></div><h2 id="what-it-can-do" tabindex="-1">What it can do <a class="header-anchor" href="#what-it-can-do" aria-label="Permalink to “What it can do”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Tools</th></tr></thead><tbody><tr><td><strong>Zones</strong></td><td>list, get, create, update labels, delete, export/import zone files, change default TTL, protection, primaries</td></tr><tr><td><strong>RRSets</strong> (record sets)</td><td>list, get, create, update labels, delete, replace all records, add records, remove records, change TTL, protection</td></tr><tr><td><strong>Actions</strong></td><td>list and get the asynchronous operations Hetzner queues behind imports and other slow changes</td></tr></tbody></table><p>The full list, with arguments, is in the <a href="/reference/tools">tool reference</a>.</p><h2 id="what-it-deliberately-does-not-do" tabindex="-1">What it deliberately does not do <a class="header-anchor" href="#what-it-deliberately-does-not-do" aria-label="Permalink to “What it deliberately does not do”">​</a></h2><ul><li><strong>It does not decide on your behalf.</strong> Every irreversible tool refuses its first call and returns a token; the second call has to repeat the identical arguments. See <a href="/guide/security">Security</a>.</li><li><strong>It does not treat the API as authoritative prose.</strong> Record values, comments, labels and zone files are written by whoever controls the zone, so everything coming back is marked as untrusted data and never quoted in a confirmation.</li><li><strong>It does not manage anything but DNS.</strong> The token is a Hetzner Cloud token with project-wide reach, but this server only ever calls <code>/v1/zones</code> paths. Give it a project that holds your zones and nothing else.</li></ul><h2 id="design-in-one-paragraph" tabindex="-1">Design in one paragraph <a class="header-anchor" href="#design-in-one-paragraph" aria-label="Permalink to “Design in one paragraph”">​</a></h2><p>Arguments go through zod schemas that reject anything which could escape a URL path — no slashes, no bare dot segments — before a request is built. Requests carry a timeout and refuse to follow redirects, so the <code>Authorization</code> header cannot be replayed at a third party. Destructive tools consult a confirmation store keyed by the target and, where a payload matters, by a hash of it. Responses pass a sanitizer that redacts secret-looking keys, truncates oversized values, and wraps the whole thing in an <code>&lt;untrusted-data&gt;</code> envelope. The credentials are deleted from the environment as soon as they have been read.</p><p>Next: <a href="/guide/getting-started">Getting started</a>.</p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};